    TreeSet<String> seen = new TreeSet<>();
    for (RehearsalResultRequest.DeviceResult dr : request.results()) {
        if (!seen.add(dr.deviceId())) {
            throw ApiException.unprocessable("RESULT_DEVICE_DUPLICATE",
