        }
    }
    for (String deviceId : seen) {
        RehearsalResultRequest.DeviceResult dr = request.results().stream()
                .filter(r -> r.deviceId().equals(deviceId)).findFirst().orElseThrow();
        normalizedResults.add(Map.of("deviceId", deviceId, "result", dr.result()));
    }
    String fingerprint = fingerprints.submitRehearsal(request.operator(), rehearsalId, normalizedResults);

