7	import com.example.starter.firmware.api.RehearsalView;
8	import com.example.starter.firmware.api.StartRehearsalRequest;
9	import com.example.starter.firmware.domain.Device;
10	import com.example.starter.firmware.domain.RehearsalDevice;
11	import com.example.starter.firmware.domain.RehearsalStatus;
12	import com.example.starter.firmware.domain.ReceiptResult;
13	import com.example.starter.firmware.domain.ReleaseGate;
14	import com.example.starter.firmware.domain.RollbackRehearsal;
15	import com.example.starter.firmware.error.ApiException;
16	import com.example.starter.firmware.repo.GateRepository;
17	import com.example.starter.firmware.repo.RehearsalRepository;
18	import com.example.starter.firmware.repo.TaskRepository;
19	import org.springframework.dao.DuplicateKeyException;
20	import org.springframework.stereotype.Service;
21	
22	import java.time.Clock;
23	import java.time.Duration;
24	import java.time.Instant;
25	import java.util.Comparator;
26	import java.util.LinkedHashMap;
27	import java.util.List;
28	import java.util.Map;
29	import java.util.TreeSet;
30	
31	/**
32	 * 固件回滚演练与正式投放门禁。
33	 *
34	 * <p>开始演练：校验规范设备集合（非空、去重排序）、版本相容（设备均登记、型号一致、当前版本等于目标版本、
35	 * 回退版本不同于目标版本）、设备无既有正式投放任务；写入 RUNNING 演练头与设备行。
36	 *
37	 * <p>提交结果：先锁演练行并对完整集合做最终校验（集合完全一致、无重复、结果合法、全部成功、结束不早于开始），
38	 * 再在同一事务内整批写入结果、置 SUCCEEDED 并授予 READY_FOR_RELEASE；任一校验失败整批回滚，不留半成品。
39	 *
40	 * <p>所有时刻为 UTC，区间按左闭右开 [startedAt, endedAt) 解释。演练、设备结果、版本与门禁结论不可变。
41	 */
42	@Service
43	public class RehearsalService {
44	
45	    /** active_key 内部分隔符：0x1F 不出现在型号/版本业务字符中，仅用于库内唯一约束键。 */
46	    private static final String ACTIVE_KEY_SEPARATOR = "\u001F";
47	
48	    private final RehearsalRepository rehearsalRepository;
49	    private final GateRepository gateRepository;
50	    private final TaskRepository taskRepository;
51	    private final DeviceService deviceService;
52	    private final IdempotencyService idempotency;
53	    private final Fingerprints fingerprints;
54	    private final Clock clock;
55	
56	    public RehearsalService(RehearsalRepository rehearsalRepository, GateRepository gateRepository,
57	                            TaskRepository taskRepository, DeviceService deviceService,
58	                            IdempotencyService idempotency, Fingerprints fingerprints, Clock clock) {
59	        this.rehearsalRepository = rehearsalRepository;
60	        this.gateRepository = gateRepository;
61	        this.taskRepository = taskRepository;
62	        this.deviceService = deviceService;
63	        this.idempotency = idempotency;
64	        this.fingerprints = fingerprints;
65	        this.clock = clock;
66	    }
67	
68	    public RehearsalView start(StartRehearsalRequest request) {
69	        List<String> normalized = normalizeDeviceIds(request.deviceIds());
70	        String fingerprint = fingerprints.startRehearsal(request.operator(), request.model(),
71	                request.targetVersion(), request.rollbackVersion(), normalized);
72	        return idempotency.execute(request.requestId(), "rehearsal.start", fingerprint, () -> {
73	            validateStart(request, normalized);
74	            String startedAt = Instant.now(clock).toString();
75	            String activeKey = request.model() + ACTIVE_KEY_SEPARATOR + request.targetVersion();
76	            long rehearsalId;
77	            try {
78	                rehearsalId = rehearsalRepository.insert(request.model(), request.targetVersion(),
79	                        request.rollbackVersion(), request.operator(), normalized.size(), startedAt, activeKey);
80	            } catch (DuplicateKeyException e) {
81	                throw ApiException.conflict("REHEARSAL_ALREADY_RUNNING",
82	                        "型号 " + request.model() + " 目标版本 " + request.targetVersion()
83	                                + " 已存在未完成演练，须先完成或放弃后再开始");
84	            }
85	            for (int i = 0; i < normalized.size(); i++) {
86	                rehearsalRepository.insertDevice(rehearsalId, normalized.get(i), i);
87	            }
88	            return viewOf(rehearsalRepository.findById(rehearsalId).orElseThrow(),
89	                    rehearsalRepository.findDevices(rehearsalId));
90	        }, RehearsalView.class);
91	    }
92	
93	    public RehearsalView submitResults(long rehearsalId, RehearsalResultRequest request) {
94	        // 结果集合规范化（按设备ID字典序），用于指纹；业务枚举合法性在事务内再校验
95	        List<Map<String, String>> normalizedResults = request.results().stream()
96	                .map(dr -> Map.of("deviceId", dr.deviceId(), "result", dr.result()))
97	                .sorted(Comparator.comparing(m -> m.get("deviceId")))
98	                .toList();
99	        long distinctDevices = request.results().stream()
100	                .map(RehearsalResultRequest.DeviceResult::deviceId).distinct().count();
101	        if (distinctDevices != request.results().size()) {
102	            throw ApiException.unprocessable("RESULT_DEVICE_DUPLICATE",
103	                    "结果集合包含重复设备：实际 " + request.results().size() + " 条，去重后 " + distinctDevices + " 台");
104	        }
105	        String fingerprint = fingerprints.submitRehearsal(request.operator(), rehearsalId, normalizedResults);
106	        return idempotency.execute(request.requestId(), "rehearsal.submit", fingerprint, () -> {
107	            RollbackRehearsal rehearsal = rehearsalRepository.findByIdForUpdate(rehearsalId)
108	                    .orElseThrow(() -> ApiException.notFound("REHEARSAL_NOT_FOUND",
109	                            "演练不存在: " + rehearsalId));
110	            if (rehearsal.status() == RehearsalStatus.SUCCEEDED) {
111	                throw ApiException.conflict("REHEARSAL_FINISHED",
112	                        "演练已结束（SUCCEEDED），结果不可改写: " + rehearsalId);
113	            }
114	            if (!rehearsal.operator().equals(request.operator())) {
115	                throw ApiException.conflict("REHEARSAL_OPERATOR_CONFLICT",
116	                        "操作者与演练发起人不一致: " + rehearsal.operator());
117	            }
118	            List<RehearsalDevice> canonical = rehearsalRepository.findDevices(rehearsalId);
119	            Map<String, ReceiptResult> submitted = validateAndParseResults(request, canonical);
120	
121	            int failedCount = 0;
122	            for (ReceiptResult result : submitted.values()) {
123	                if (result == ReceiptResult.FAILED) {
124	                    failedCount++;
125	                }
126	            }
127	            if (failedCount > 0) {
128	                int successCount = canonical.size() - failedCount;
129	                throw ApiException.unprocessable("REHEARSAL_FAILED",
130	                        "演练存在失败设备：实际成功 " + successCount + " 台，要求 " + canonical.size()
131	                                + " 台，差额 " + failedCount + " 台；本次结果整批驳回，不产生部分就绪状态");
132	            }
133	
134	            Instant startedAt = Instant.parse(rehearsal.startedAtUtc());
135	            Instant endedAt = Instant.now(clock);
136	            if (endedAt.isBefore(startedAt)) {
137	                throw ApiException.unprocessable("REHEARSAL_END_BEFORE_START",
138	                        "演练结束时刻 " + endedAt + " 早于开始时刻 " + startedAt + "（UTC，区间左闭右开）");
139	            }
140	            long durationSeconds = Duration.between(startedAt, endedAt).toSeconds();
141	            String endedAtUtc = endedAt.toString();
142	
143	            // 完整最终状态校验通过后，整批结果与门禁在同一事务提交
